solid.code:
import { Component, JSX, splitProps } from 'solid-js';
import * as CursorTooltipPrimitive from '@exhuma/core';

export interface CursorTooltipProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const CursorTooltip: Component<CursorTooltipProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <CursorTooltipPrimitive.CursorTooltip
      class={`relative inline-block cursor-pointer ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </CursorTooltipPrimitive.CursorTooltip>
  );
};

