import { CursorTooltip } from '@exhuma/core';

class ExhumaCursorTooltipElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-cursor-tooltip');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-cursor-tooltip')) {
  customElements.define('exhuma-cursor-tooltip', ExhumaCursorTooltipElement);
}

react-native.code:
import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as CursorTooltipPrimitive from '@exhuma/core';

export interface CursorTooltipProps extends ViewProps {
  children?: React.ReactNode;
}

export function CursorTooltip({ style, children, ...props }: CursorTooltipProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: '#e2e8f0',
    backgroundColor: '#ffffff',
    padding: 20,
    overflow: 'hidden',
  },
});

